CREATE TABLE "users" (
  "user_id" uuid PRIMARY KEY
);

CREATE TABLE "profiles" (
  "profile_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" uuid NOT NULL UNIQUE REFERENCES users(user_id),
  "full_name" varchar NOT NULL,
  "headline" varchar NOT NULL,
  "location" varchar,
  "summary" text,
  "career_goals_description" text
);

CREATE TABLE "skills" (
  "skill_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "profile_id" integer NOT NULL REFERENCES profiles(profile_id) ON DELETE CASCADE,
  "name" varchar NOT NULL,
  "proficiency" varchar
);


CREATE TABLE "projects" (
  "project_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "profile_id" integer NOT NULL REFERENCES profiles(profile_id) ON DELETE CASCADE,
  "title" varchar NOT NULL,
  "subtitle" varchar,
  "start_date" date,
  "end_date" date,
  "description" text,
  "url" varchar
);

CREATE TABLE "project_skills" (
  "project_id" integer NOT NULL REFERENCES projects(project_id) ON DELETE CASCADE,
  "skill_id" integer NOT NULL REFERENCES skills(skill_id) ON DELETE CASCADE,
  PRIMARY KEY ("project_id", "skill_id")
);

CREATE TABLE "work_experiences" (
  "work_experience_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "profile_id" integer NOT NULL REFERENCES profiles(profile_id) ON DELETE CASCADE,
  "title" varchar NOT NULL,
  "company" varchar NOT NULL,
  "location" varchar,
  "start_date" date,
  "end_date" date,
  "description" text
);

CREATE TABLE "languages" (
  "language_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "profile_id" integer NOT NULL REFERENCES profiles(profile_id) ON DELETE CASCADE,
  "language" varchar NOT NULL,
  "proficiency" varchar NOT NULL
);

CREATE TABLE "degrees" (
  "degree_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "profile_id" integer NOT NULL REFERENCES profiles(profile_id) ON DELETE CASCADE,
  "title" varchar NOT NULL,  
  "school" varchar NOT NULL,
  "location" varchar,
  "finished_date" date,
  "gpa" decimal,
  "major" varchar,
  "minor" varchar,
  "additional_information" text
);

CREATE TABLE "hobbies" (
  "hobby_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "profile_id" integer NOT NULL REFERENCES profiles(profile_id) ON DELETE CASCADE,
  "name" varchar NOT NULL,
  "description" text
);